card_mod.style:
:host {
  {% set c = state_attr('[[entity]]','trend_color') %}
  {% if c %}
    --state-icon-color: {{ c }} !important;
    --paper-item-icon-color: {{ c }} !important;
    --mdc-theme-primary: {{ c }} !important;
  {% endif %}
}
:host ha-icon,
:host ha-state-icon,
:host state-badge,
:host state-badge * {
  color: var(--state-icon-color) !important;
  fill:  var(--state-icon-color) !important;
}

ha-card {
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
  padding: 0 !important;
}

